import AppKit

/// polls the pasteboard's change count. it's one integer read, so it's cheap.
final class Watcher {
    private var last = NSPasteboard.general.changeCount
    private var timer: Timer?
    private let work = DispatchQueue(label: "party.chee.clipcat.watcher", qos: .utility)

    /// password managers and friends mark things they don't want remembered
    private static let secret: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.4, repeats: true) { [weak self] _ in self?.check() }
        timer?.tolerance = 0.2
    }

    func check() {
        let pb = NSPasteboard.general
        guard pb.changeCount != last else { return }
        last = pb.changeCount
        capture(pb)
    }

    private func capture(_ pb: NSPasteboard) {
        let types = Set((pb.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.secret) else { return }

        if let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            let body = urls.map(\.path).joined(separator: "\n")
            Store.shared.add(.file, body: body, hash: "f:" + Store.hash(Data(body.utf8)))
            changed()
        } else if let text = pb.string(forType: .string),
                  !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            Store.shared.add(.text, body: text, hash: "t:" + Store.hash(Data(text.utf8)))
            changed()
        } else if let data = pb.data(forType: .png) ?? pb.data(forType: .tiff) {
            work.async { [weak self] in self?.keep(image: data) }
        }
    }

    private func keep(image data: Data) {
        let isPNG = data.starts(with: [0x89, 0x50, 0x4E, 0x47])
        guard let png = isPNG ? data : NSBitmapImageRep(data: data)?.representation(using: .png, properties: [:])
        else { return }
        let hash = Store.hash(png)
        let url = Store.shared.imageDir.appendingPathComponent(hash + ".png")
        if !FileManager.default.fileExists(atPath: url.path) {
            try? png.write(to: url, options: .atomic)
        }
        if let added = Store.shared.add(.image, body: "", image: url.path, hash: "i:" + hash), !added.seen {
            Seer.look(at: url.path, id: added.id)
        }
        DispatchQueue.main.async { self.changed() }
    }

    private func changed() {
        NotificationCenter.default.post(name: .clipsChanged, object: nil)
    }
}
